<div id="admin-activity-panel" class="admin-panel" role="tabpanel" aria-labelledby="tab-activity" <?= $adminInitialSection !== 'activity' ? 'hidden' : '' ?>>
                        <div class="panel-header"><div><p class="eyebrow">Audit trail</p><h2>Activity log</h2><p>Administrative actions and security events.</p></div></div>
                        <div class="activity-filters" id="activity-extra-filters" aria-label="Filter activity log">
                            <label>Action type<select id="activity-action-filter" data-action-change="handleActivityFilterChange()"><option value="">All actions</option><option value="approve_resident">Resident verified</option><option value="reject_resident">Resident rejected</option><option value="proof_viewed">Proof viewed</option><option value="request_approved">Request approved</option><option value="request_rejected">Request rejected</option><option value="request_ready_for_pickup">Marked ready for pickup</option><option value="request_completed">Request completed</option><option value="disclosure_published">Disclosure posted</option><option value="disclosure_draft_saved">Draft saved</option><option value="disclosure_draft_deleted">Draft deleted</option><option value="disclosure_edited">Disclosure edited</option><option value="disclosure_unpublished">Disclosure unpublished</option><option value="admin_login">Admin logged in</option><option value="admin_login_mfa">Admin sign-in completed</option><option value="admin_mfa_failed">Authenticator check failed</option><option value="resident_login_success">Resident sign-in</option><option value="failed_admin_login">Failed admin sign-in</option><option value="failed_resident_login">Failed resident sign-in</option><option value="admin_deleted">Admin deleted</option></select></label>
                            <label>From<input id="activity-from-date" type="date" data-action-change="handleActivityFilterChange()"></label>
                            <label>To<input id="activity-to-date" type="date" data-action-change="handleActivityFilterChange()"></label>
                            <label class="activity-search-label">Search<input id="activity-search" type="search" placeholder="Search actor, action, or details" data-action-input="debouncedLoadAdminActivity()"></label>
                        </div>
                        <div class="activity-tools"><div class="activity-presets"><button class="activity-chip" data-activity-preset="today" type="button" data-action-click="setActivityPreset('today')">Today</button><button class="activity-chip" data-activity-preset="week" type="button" data-action-click="setActivityPreset('week')">Last 7 days</button><button class="activity-chip" data-activity-preset="month" type="button" data-action-click="setActivityPreset('month')">This month</button><button class="btn-outline activity-filter-toggle" type="button" aria-expanded="false" aria-controls="activity-extra-filters" data-action-click="toggleActivityExtraFilters(this)"><i class="fas fa-filter" aria-hidden="true"></i> Filters</button><button class="activity-clear" type="button" data-action-click="clearActivityFilters()" hidden>Clear filters</button></div><span id="activity-result-count">Showing 0-0 of 0</span><button class="btn-outline activity-export" type="button" data-action-click="exportActivityCsv()"><i class="fas fa-download" aria-hidden="true"></i> Export CSV</button></div>
                        <div class="card full-width-card table-card admin-table-scroll activity-admin-table-wrap"><table class="admin-table activity-admin-table"><caption class="visually-hidden">Read-only administrative activity log</caption><thead><tr><th scope="col"><button class="activity-sort" data-action-click="sortActivity('date')">Time <span class="activity-sort-arrow" id="activity-sort-date">↕</span></button></th><th scope="col"><button class="activity-sort" data-action-click="sortActivity('admin')">Actor <span class="activity-sort-arrow" id="activity-sort-admin">↕</span></button></th><th scope="col"><button class="activity-sort" data-action-click="sortActivity('action')">Action <span class="activity-sort-arrow" id="activity-sort-action">↕</span></button></th><th scope="col">Details</th></tr></thead><tbody id="admin-activity-list"><tr><td colspan="4" class="table-empty-state">Loading activity…</td></tr></tbody></table></div>
                        <div id="admin-activity-mobile-list" class="activity-mobile-list" aria-live="polite"></div>
                        <nav class="activity-pagination" aria-label="Activity log pages"><span id="activity-page-status">Page 1</span><div><button class="btn-outline" type="button" id="activity-prev" data-action-click="loadAdminActivity(activityCurrentPage - 1)" disabled>Previous</button><button class="btn-outline" type="button" id="activity-next" data-action-click="loadAdminActivity(activityCurrentPage + 1)" disabled>Next</button></div></nav>
                    </div>
